using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = Path.Combine("..", "build.binlog");
var build = BinaryLog.ReadBuild(binlogPath);

// Check for source file contents embedded in binlog
Console.WriteLine("=== Source Files Referenced ===");
var files = new HashSet<string>();
build.VisitAllChildren<Error>(error => {
    if (!string.IsNullOrEmpty(error.File)) files.Add(error.File);
});
foreach (var f in files.OrderBy(x => x)) Console.WriteLine($"  {f}");

// Look at the project evaluation to find package references
Console.WriteLine("\n=== Looking for PackageReference items ===");
build.VisitAllChildren<AddItem>(item => {
    if (item.Name == "PackageReference") {
        var project = "";
        BaseNode node = item.Parent;
        while (node != null) {
            if (node is Project p) { project = p.Name; break; }
            node = node.Parent;
        }
        foreach (var child in item.Children.OfType<Item>()) {
            Console.WriteLine($"  {project}: {child.Name} {child.Text}");
        }
    }
});

// Look for project references
Console.WriteLine("\n=== ProjectReference items ===");
build.VisitAllChildren<AddItem>(item => {
    if (item.Name == "ProjectReference") {
        var project = "";
        BaseNode node = item.Parent;
        while (node != null) {
            if (node is Project p) { project = p.Name; break; }
            node = node.Parent;
        }
        foreach (var child in item.Children.OfType<Item>()) {
            Console.WriteLine($"  {project}: {child.Name} {child.Text}");
        }
    }
});

// Check for failed project build results
Console.WriteLine("\n=== Build Results ===");
build.VisitAllChildren<Microsoft.Build.Logging.StructuredLogger.Target>(t => {
    if (t.Name == "CoreCompile") {
        var project = "";
        BaseNode node = t.Parent;
        while (node != null) {
            if (node is Project p) { project = p.Name; break; }
            node = node.Parent;
        }
        // Check if any errors in this target
        var hasErrors = false;
        t.VisitAllChildren<Error>(e => hasErrors = true);
        if (hasErrors) Console.WriteLine($"  COMPILE FAILED: {project}");
    }
});
EOF
