var build = BinaryLog.ReadBuild(binlogPath);

// Look for all items in Services.csproj to find if Newtonsoft.Json is referenced
Console.WriteLine("=== All AddItem in Services.csproj ===");
build.VisitAllChildren<AddItem>(item => {
    var project = "";
    BaseNode node = item.Parent;
    while (node != null) {
        if (node is Project p) { project = p.Name; break; }
        node = node.Parent;
    }
    if (project == "Services.csproj") {
        foreach (var child in item.Children.OfType<Item>()) {
            if (item.Name == "PackageReference" || item.Name == "Reference" || child.Name.Contains("Newtonsoft")) {
                Console.WriteLine($"  {item.Name}: {child.Name} {child.Text}");
            }
        }
    }
});

// Look at NuGet restore messages
Console.WriteLine("\n=== NuGet/Restore Messages ===");
build.VisitAllChildren<Message>(m => {
    if (m.Text != null && (m.Text.Contains("Newtonsoft") || m.Text.Contains("NU1"))) {
        Console.WriteLine($"  {m.Text.Substring(0, Math.Min(200, m.Text.Length))}");
    }
});

// Get the source content from the binlog if available
Console.WriteLine("\n=== Looking for source file content ===");
build.VisitAllChildren<Microsoft.Build.Logging.StructuredLogger.Task>(t => {
    if (t.Name == "Csc") {
        var project = "";
        BaseNode node = t.Parent;
        while (node != null) {
            if (node is Project p) { project = p.Name; break; }
            node = node.Parent;
        }
        if (project == "Services.csproj") {
            Console.WriteLine($"  Csc task in Services.csproj, children: {t.Children.Count}");
            foreach (var child in t.Children.Take(5)) {
                Console.WriteLine($"    {child.GetType().Name}: {child.ToString()?.Substring(0, Math.Min(150, child.ToString()?.Length ?? 0))}");
            }
        }
    }
});

// Get all messages from Services.csproj
Console.WriteLine("\n=== Key Messages from Services.csproj ===");
build.VisitAllChildren<Message>(m => {
    var project = "";
    BaseNode node = m.Parent;
    while (node != null) {
        if (node is Project p) { project = p.Name; break; }
        node = node.Parent;
    }
    if (project == "Services.csproj" && m.Text != null && (m.Text.Contains("Reference") || m.Text.Contains("Package"))) {
        Console.WriteLine($"  {m.Text.Substring(0, Math.Min(200, m.Text.Length))}");
    }
});
